@dataclass
class ContactRecord:
    id: int
    email: str
    phone: str

    def to_dict(self) -> dict:
        local, _, domain = self.email.partition('@')
        digits = ''.join(ch for ch in self.phone if ch.isdigit())
        return {
            'id': self.id,
            'email': f'{local[:1]}***@{domain}',
            'phone': f'***{digits[-4:]}',
        }


