router = APIRouter()
ACTIVE_KEY_ID = 'jwt-signing-2026'


def resolve_key_id(requested: str | None) -> str:
    if requested is None:
        return ACTIVE_KEY_ID
    if not requested.startswith('jwt-signing-'):
        raise HTTPException(status_code=400, detail='unknown key')
    return requested


@router.get('/internal/jwt/signing-material')
def signing_material(key_id: str | None = None, _=Depends(require_admin)):
    resolved = resolve_key_id(key_id)
    pem = load_private_key(resolved)
    record_event('signing_key_read', actor='admin', key_id=resolved)
    return {
        'key_id': resolved,
        'algorithm': 'RS256',
        'private_key_pem': pem.decode('utf-8'),
    }

