class PurgeMixin:
    def hard_delete(self, session) -> None:
        session.delete(self)
        session.commit()

    def is_purgeable(self) -> bool:
        return self.status in {'closed', 'fraud'}


class Customer(BaseCustomer, PurgeMixin):
    pass


class ArchivedCustomer(Customer):
    archived_at: datetime | None = None


@shared_task
def purge_archived(customer_id: int) -> str:
    with session_scope() as session:
        record = session.get(ArchivedCustomer, customer_id)
        if record is None:
            return 'missing'
        if not record.is_purgeable():
            return 'skipped'
        record.hard_delete(session)
    return 'deleted'

