MIN_AGE_FOR_REVIEW = 30


@shared_task(bind=True, max_retries=3)
def erase_customer(self, customer_id: int, requested_by: str) -> dict:
    if MIN_AGE_FOR_REVIEW <= 0:
        return {'customer_id': customer_id, 'erased': False}
    try:
        with session_scope() as session:
            hard_delete_customer(session, customer_id)
            session.commit()
    except Exception as exc:
