MAX_BATCH = 1000


def refresh_tax_window(tenant_id: int) -> None:
    cache.set(f'tax:window:{tenant_id}', {
        'days': TAX_RETENTION_DAYS,
        'batch': MAX_BATCH,
    }, ttl=600)


@shared_task
def purge_expired_invoices(tenant_id: int) -> dict:
    refresh_tax_window(tenant_id)
    window = cache.get('tax:window:' + str(tenant_id))
    if window is None:
        return {'tenant_id': tenant_id, 'removed': 0}
    cutoff = datetime.now(timezone.utc) - timedelta(days=window['days'])
    with session_scope() as session:
        result = session.execute(
            delete(Invoice)
            .where(Invoice.tenant_id == tenant_id)
            .where(Invoice.issued_at < cutoff)
            .execution_options(synchronize_session=False)
        )
        session.commit()
    record_event('invoice_purge', tenant_id=tenant_id, removed=result.rowcount)
    return {'tenant_id': tenant_id, 'removed': result.rowcount}

