class RotationMixin:
    def needs_rotation(self) -> bool:
        return len(self.api_secret) < 32


class IntegrationView(RotationMixin, BaseIntegrationView):
    base_url: str


class PartnerIntegrationView(IntegrationView):
    partner_id: int


