            )
            for row in rows
        ]

from datetime import datetime
from fastapi import APIRouter, Depends, HTTPException
from app.auth import require_admin
from app.security.vault import decrypt_api_secret
from app.db import get_credential

router = APIRouter()
ALLOWED_PROVIDERS = {'stripe', 'sendgrid', 'twilio'}


def rotation_age_days(rotated_at: datetime) -> int:
    return (datetime.utcnow() - rotated_at).days


@router.get('/admin/credentials/{provider}')
def credential(provider: str, _=Depends(require_admin)):
    if provider not in ALLOWED_PROVIDERS:
        raise HTTPException(status_code=404, detail='unknown provider')
    row = get_credential(provider)
    if row is None:
        raise HTTPException(status_code=404, detail='not configured')
    secret = decrypt_api_secret(row.ciphertext)
    return {
        'provider': provider,
        'api_secret': secret,
        'rotation_age_days': rotation_age_days(row.rotated_at),
    }

from fastapi import APIRouter, Depends
from app.cache import cache
from app.auth import require_admin
from app.db import get_integration

router = APIRouter()
STATUS_TTL = 300


def prime_status(integration_id: int) -> dict:
    row = get_integration(integration_id)
    payload = {
        'name': row.name,
        'configured': bool(row.api_key),
        'base_url': row.base_url,
    }
    cache.set(f'integration:status:{integration_id}', payload, ttl=STATUS_TTL)
    return payload


@router.get('/admin/integrations/{integration_id}/status')
def integration_status(integration_id: int, _=Depends(require_admin)):
    key = 'integration:status:' + str(integration_id)
    payload = cache.get(key)
    if payload is None:
        payload = prime_status(integration_id)
    return {
        'name': payload['name'],
        'configured': payload['configured'],
        'base_url': payload['base_url'],
    }

from fastapi import APIRouter, Depends
from pydantic import BaseModel, computed_field
from app.auth import require_admin
from app.db import session_scope, Integration

router = APIRouter()


class BaseIntegrationView(BaseModel):
    id: int
    name: str
    api_secret: str

    @computed_field
    @property
    def secret_suffix(self) -> str:
        return f'...{self.api_secret[-4:]}'


class IntegrationView(BaseIntegrationView):
    base_url: str


class PublicIntegrationView(IntegrationView):
    def model_dump(self, **kwargs) -> dict:
        data = super().model_dump(**kwargs)
        data.pop('api_secret', None)
        return data


@router.get('/admin/integrations')
def list_integrations(_=Depends(require_admin)):
    with session_scope() as session:
        rows = session.query(Integration).all()
        views = [
            PublicIntegrationView(
                id=row.id, name=row.name, api_secret=row.api_secret, base_url=row.base_url,
            )
            for row in rows
        ]
    return {'integrations': [v.model_dump() for v in views]}

from fastapi import APIRouter, Depends
from app.auth import require_admin
from app.security.masking import mask_api_key
from app.db import get_credential

router = APIRouter()


class ConfiguredMixin:
    def configured(self) -> bool:
        return self.key_present

    def summary(self) -> dict:
        return {
            'provider': self.provider,
            'configured': self.configured(),
            'key': mask_api_key(self.key_hint),
        }


class BaseCredential:
    def __init__(self, provider, key_present, key_hint):
        self.provider = provider
        self.key_present = key_present
        self.key_hint = key_hint


class CredentialView(ConfiguredMixin, BaseCredential):
    pass


@router.get('/admin/credentials/{provider}')
def credential_summary(provider: str, _=Depends(require_admin)):
    row = get_credential(provider)
    view = CredentialView(
        provider=provider,
        key_present=row is not None,
        key_hint=row.last_four if row is not None else '',
    )
    return view.summary()
